const upsertSandboxCharge = `-- name: UpsertSandboxCharge :exec
INSERT INTO payment_sandbox_charges (order_id, status, amount_vnd, event_id, updated_at)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (order_id) DO UPDATE SET status = EXCLUDED.status, amount_vnd = EXCLUDED.amount_vnd,
    event_id = EXCLUDED.event_id, updated_at = EXCLUDED.updated_at
`

type UpsertSandboxChargeParams struct {
	OrderID   uuid.UUID `json:"order_id"`
	Status    string    `json:"status"`
	AmountVnd int64     `json:"amount_vnd"`
	EventID   string    `json:"event_id"`
	Now       time.Time `json:"now"`
}

func (q *Queries) UpsertSandboxCharge(ctx context.Context, arg UpsertSandboxChargeParams) error {
	_, err := q.db.Exec(ctx, upsertSandboxCharge,
		arg.OrderID,
		arg.Status,
		arg.AmountVnd,
		arg.EventID,
		arg.Now,
	)
	return err
}
